-- State transitions declared for UserInput (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION survey.survey_user_inputs_state_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."state" IS DISTINCT FROM OLD."state" AND NOT (
           (COALESCE(OLD."state"::text, ''), COALESCE(NEW."state"::text, '')) IN (('in_progress', 'done'), ('new', 'in_progress'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: survey_user_inputs.state % -> %', OLD."state", NEW."state";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS survey_user_inputs_state_transition_check ON survey.survey_user_inputs;
CREATE TRIGGER survey_user_inputs_state_transition_check
    BEFORE UPDATE OF "state" ON survey.survey_user_inputs
    FOR EACH ROW EXECUTE FUNCTION survey.survey_user_inputs_state_transition_check();
